INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('00d1c243-0301-4212-a7dd-27a82bdc3fa0'::uuid, 'card_description', 'Into the lake of Llyn Fawr, in a glacial cirque, went two bronze cauldrons and axeheads, part of a hoard of weapons and tools that appears to have been placed as votive offerings.', 'Two bronze cauldrons appear to have been placed in this lake as offerings. They belong to a hoard of late Bronze Age and early Iron Age weapons and tools, in a glacial hollow under a ridge.', 'teaser-card-s041:00d1c243-0301-4212-a7dd-27a82bdc3fa0:card_description', 'teaser-card-s041 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '7b8613084b6500fed6d0707797b9139697fce3e307e4b31330fa378557ab3fc6|1c4824b7835c762e3a42b35925c0983212f86fb896a07afdd55d044d8484c2ba|1c4824b7835c762e3a42b35925c0983212f86fb896a07afdd55d044d8484c2ba', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Two bronze cauldrons appear to have been placed in this lake as offerings. They belong to a hoard of late Bronze Age and early Iron Age weapons and tools, in a glacial hollow under a ridge."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "two bronze cauldrons are among the finds [S6]; they appear to have been placed in the lake [S7]; they appear to have been placed there as offerings [S7]; the site is a lake [S5]; the cauldrons belong to a hoard [S2, S6]; the hoard is of weapons and tools [S2]; the hoard dates from the late Bronze Age and early Iron Age [S2]; the lake lies in a glacial hollow [S1]; the lake lies under a ridge [S1, S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Two bronze cauldrons appear to have been placed in this lake as offerings. [SUPPORTED: https://cynonvalleymuseum.wales/2021/11/20/the-iron-age-llyn-fawr-hoard/]; There are two cauldrons. [SUPPORTED: https://gwrachtimeline.co.uk/llyn-fawr-hoard-article]; The cauldrons are made of bronze. [SUPPORTED: https://cynonvalleymuseum.wales/2021/11/20/the-iron-age-llyn-fawr-hoard/]; The cauldrons were placed in this lake. [SUPPORTED: https://museum.wales/collections/online/object/8152744e-4556-3952-b986-1b7b325ad68f/Late-Bronze-Age-bronze-cauldron/]; The cauldrons belong to a hoard. [SUPPORTED: https://museum.wales/collections/online/object/8152744e-4556-3952-b986-1b7b325ad68f/Late-Bronze-Age-bronze-cauldron/]; The hoard is of the late Bronze Age. [SUPPORTED: https://gwrachtimeline.co.uk/llyn-fawr-hoard-article]; The hoard is of the early Iron Age. [SUPPORTED: https://cynonvalleymuseum.wales/2021/11/20/the-iron-age-llyn-fawr-hoard/]; The hoard contains weapons. [SUPPORTED: https://gwrachtimeline.co.uk/llyn-fawr-hoard-article]; The hoard contains tools. [SUPPORTED: https://gwrachtimeline.co.uk/llyn-fawr-hoard-article]; The lake lies in a glacial hollow. [SUPPORTED: https://en.wikipedia.org/wiki/Craig_y_Llyn]; The glacial hollow lies under a ridge. [SUPPORTED: https://cynonvalleymuseum.wales/2021/11/20/the-iron-age-llyn-fawr-hoard/]"}]'::jsonb),
    ('02e075bc-19b7-4522-92ff-c07f230b5678'::uuid, 'card_description', 'On the banks of the lower Machaquila River lies Machaquila, a ruined Maya city of abundant sculpted monuments, unusual in its region for lacking both a ballcourt and an E-Group.', 'No ballcourt and no astronomy complex: this ruined Maya city lacks both. Nearby cities often have them, but this city stands out for its many sculpted monuments, not its buildings or size.', 'teaser-card-s041:02e075bc-19b7-4522-92ff-c07f230b5678:card_description', 'teaser-card-s041 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'bc6af0b769751ed736809384e45e542fd62fe6e923c0010909f81e98374a6fe7|165310bdbf02bb12bb1785245b58113a4d9e9dffa2b1d56056a0d00a6c6b1253|165310bdbf02bb12bb1785245b58113a4d9e9dffa2b1d56056a0d00a6c6b1253', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "No ballcourt and no astronomy complex: this ruined Maya city lacks both. Nearby cities often have them, but this city stands out for its many sculpted monuments, not its buildings or size."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the city has no ballcourt [S6]; the city has no astronomical complex [S6]; it is a ruined city [S1]; it is a Maya city [S1]; neighbouring cities often have these arrangements [S6]; the city stands out for its many sculpted monuments [S7]; it does not stand out for its buildings or size [S7]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "This ruined Maya city lacks a ballcourt. [SUPPORTED: http://www.asociaciontikal.com/simposio-18-ano-2004/36-laporte-mejia-y-chocon-04-doc/]; This city lacks an astronomy complex (an E-Group). [SUPPORTED: http://www.asociaciontikal.com/simposio-18-ano-2004/36-laporte-mejia-y-chocon-04-doc/]; It lacks both (no ballcourt and no astronomy complex). [SUPPORTED: https://revistas.ucm.es/index.php/REAA/es/article/download/REAA1111120175A/22348/23509]; It is a ruined Maya city. [SUPPORTED: https://revistas.ucm.es/index.php/REAA/es/article/download/REAA1111120175A/22348/23509]; Nearby cities often have a ballcourt. [SUPPORTED: http://www.asociaciontikal.com/simposio-18-ano-2004/36-laporte-mejia-y-chocon-04-doc/]; Nearby cities often have an astronomy complex (E-Group). [SUPPORTED: http://www.asociaciontikal.com/simposio-18-ano-2004/36-laporte-mejia-y-chocon-04-doc/]; This city stands out for its many sculpted monuments. [SUPPORTED: http://www.asociaciontikal.com/simposio-18-ano-2004/36-laporte-mejia-y-chocon-04-doc/]; It does not stand out for its buildings. [SUPPORTED: http://www.asociaciontikal.com/simposio-18-ano-2004/36-laporte-mejia-y-chocon-04-doc/]; It does not stand out for its size. [SUPPORTED: http://www.asociaciontikal.com/simposio-18-ano-2004/36-laporte-mejia-y-chocon-04-doc/]"}]'::jsonb),
    ('02f1050b-2a58-41c6-86b2-62481e249e05'::uuid, 'card_description', 'Hilltop necropolis at ~3,820 m in the Ancash highlands with rectangular, semicircular, and quadrangular stone structures. The twin villages of Yanaque and Quilcamarca share a mountain and a myth.', 'A woman named Pichanamaria swept the streets with a broom, local legend says. In the tale, her sweeping caused an illness that killed the people of two hilltop villages, rivals over water.', 'teaser-card-s041:02f1050b-2a58-41c6-86b2-62481e249e05:card_description', 'teaser-card-s041 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'a3d8063087e8df68687a87c5665fa0030ebd6900cdfab27a6970349bc92e477b|7d3da97cf77174d1838a8c7a1cfff5f9900d2353ec873944c8d937dfcfb5266a|7d3da97cf77174d1838a8c7a1cfff5f9900d2353ec873944c8d937dfcfb5266a', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A woman named Pichanamaria swept the streets with a broom, local legend says. In the tale, her sweeping caused an illness that killed the people of two hilltop villages, rivals over water."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "according to local legend, a woman was named Pichanamaria [S3]; in the legend, she swept the streets with a broom [S3]; in the legend, her sweeping caused an illness [S3]; the illness killed the people of two villages [S3]; the two villages stood on hilltops [S1]; the two villages were rivals over water [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A woman named Pichanamaria swept the streets with a broom, local legend says. [SUPPORTED: https://web.archive.org/web/20140423043001/http://www.mincetur.gob.pe/TURISMO/OTROS/inventario%20turistico/Ficha.asp?cod_Ficha=2896]; The figure of the legend is a woman named Pichanamaria. [SUPPORTED: https://web.archive.org/web/20140423043001/http://www.mincetur.gob.pe/TURISMO/OTROS/inventario%20turistico/Ficha.asp?cod_Ficha=2896]; She swept the streets with a broom. [SUPPORTED: https://web.archive.org/web/20140423043001/http://www.mincetur.gob.pe/TURISMO/OTROS/inventario%20turistico/Ficha.asp?cod_Ficha=2896]; This is told as a local legend (a tale). [SUPPORTED: https://web.archive.org/web/20140423043001/http://www.mincetur.gob.pe/TURISMO/OTROS/inventario%20turistico/Ficha.asp?cod_Ficha=2896]; In the tale, her sweeping caused an illness. [SUPPORTED: https://web.archive.org/web/20140423043001/http://www.mincetur.gob.pe/TURISMO/OTROS/inventario%20turistico/Ficha.asp?cod_Ficha=2896]; The illness killed the people of two villages. [SUPPORTED: https://web.archive.org/web/20140423043001/http://www.mincetur.gob.pe/TURISMO/OTROS/inventario%20turistico/Ficha.asp?cod_Ficha=2896]; The two villages stood on hilltops. [SUPPORTED: https://web.archive.org/web/20140423043001/http://www.mincetur.gob.pe/TURISMO/OTROS/inventario%20turistico/Ficha.asp?cod_Ficha=2896]; The two villages were rivals over water. [SUPPORTED: https://web.archive.org/web/20140423043001/http://www.mincetur.gob.pe/TURISMO/OTROS/inventario%20turistico/Ficha.asp?cod_Ficha=2896]"}]'::jsonb),
    ('05d4e028-3cd3-46e8-ad35-aaaf70a3077c'::uuid, 'card_description', 'Raised around 380 BCE in ancient Lycia, the Heroon of Trysa was a tomb whose square outer wall bore a figural frieze of circa 152 plates, brought to Vienna in 1882.', 'A gymnasium teacher discovered this tomb in 1841 during his field research. The tomb''s frieze of plates once decorated its square outer wall, and those plates now sit in a museum in Vienna.', 'teaser-card-s041:05d4e028-3cd3-46e8-ad35-aaaf70a3077c:card_description', 'teaser-card-s041 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'd9d5ff1c0f66ef730266f30fb3fe9314f3a7b409fe3e38ce8e72907a6144f4a8|74823ccefee722fa0f9e5cc0a6c58c6e2bcaf7404ced1955159ffcdf433d27ff|74823ccefee722fa0f9e5cc0a6c58c6e2bcaf7404ced1955159ffcdf433d27ff', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A gymnasium teacher discovered this tomb in 1841 during his field research. The tomb''s frieze of plates once decorated its square outer wall, and those plates now sit in a museum in Vienna."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site is a tomb [S1]; a gymnasium teacher discovered it [S2]; he discovered it in 1841 [S2]; he discovered it during his field research [S2]; the tomb had a frieze of plates [S3]; the frieze once (originally) decorated the tomb''s square outer wall [S3]; the plates are now in a museum in Vienna [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-001 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A gymnasium teacher discovered this tomb in 1841 during his field research. [SUPPORTED: https://de.wikipedia.org/wiki/Heroon_von_Trysa]; The discoverer was a gymnasium teacher. [SUPPORTED: https://de.wikipedia.org/wiki/Heroon_von_Trysa]; The discovery was in 1841. [SUPPORTED: https://www.worldhistory.org/article/1584/the-heroon-of-trysa-a-lycian-tomb-reappears/]; He discovered it during his field research. [SUPPORTED: https://de.wikipedia.org/wiki/Heroon_von_Trysa]; It is a tomb. [SUPPORTED: https://www.khm.at/en/artworks/das-heroon-von-trysa-1336040]; The tomb''s frieze consisted of plates. [SUPPORTED: https://de.wikipedia.org/wiki/Heroon_von_Trysa]; The frieze once decorated the tomb''s outer (enclosing) wall. [SUPPORTED: https://www.khm.at/en/artworks/das-heroon-von-trysa-1336040]; That outer wall is square. [SUPPORTED: https://www.worldhistory.org/article/1584/the-heroon-of-trysa-a-lycian-tomb-reappears/]; Those plates now sit in a museum in Vienna. [SUPPORTED: https://de.wikipedia.org/wiki/Heroon_von_Trysa]"}]'::jsonb),
    ('090861ff-b5c9-4848-84e3-9407cf27189e'::uuid, 'card_description', '2nd century BC -- Rome''s oldest stone bridge. Rebuilt in stone to span the Tiber between the Forum Boarium and Trastevere. Today a single arch survives mid-river: Ponte Rotto, the Broken Bridge.', 'Only a single arch survives, standing alone in the middle of the river. Built in wood, then rebuilt in stone in the 2nd century BC, the bridge is the oldest Roman stone bridge in Rome.', 'teaser-card-s041:090861ff-b5c9-4848-84e3-9407cf27189e:card_description', 'teaser-card-s041 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '7f832ab19313400494db455e2a979593897c1315a687301863de7b2fda8de255|6b7b7679e5b89570ecff28f5369d79928392662539ee7478156f3879eb7da817|6b7b7679e5b89570ecff28f5369d79928392662539ee7478156f3879eb7da817', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Only a single arch survives, standing alone in the middle of the river. Built in wood, then rebuilt in stone in the 2nd century BC, the bridge is the oldest Roman stone bridge in Rome."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "today only a single arch survives [S3]; the arch stands in the middle of the river [S3]; the bridge was originally built in wood [S1]; it was rebuilt in stone in the 2nd century BC [S1]; it is the oldest Roman stone bridge in Rome [S1]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Only a single arch of this bridge (Ponte Emilio / Ponte Rotto, Rome) survives. [SUPPORTED: https://www.comune.roma.it/web/it/notizia/ultima-arcata-strana-storia-ponte-rotto.page]; The surviving arch stands alone in the middle of the river. [SUPPORTED: https://en.wikipedia.org/wiki/Ponte_Palatino]; The bridge was first built in wood. [SUPPORTED: https://www.comune.roma.it/web/it/notizia/ultima-arcata-strana-storia-ponte-rotto.page]; The bridge was rebuilt in stone in the 2nd century BC. [SUPPORTED: https://www.comune.roma.it/web/it/notizia/ultima-arcata-strana-storia-ponte-rotto.page]; The bridge is the oldest Roman stone bridge in Rome. [SUPPORTED: https://en.wikipedia.org/wiki/Masonry_bridge]"}]'::jsonb),
    ('0aa03558-b60a-46d3-8a77-7dcce6f7e015'::uuid, 'card_description', 'Tambo Viejo spreads over approximately 44 hectares of Arequipa: a large rectangular plaza to the north, a labyrinth of structures to the south, and Early Nasca pottery among its traces.', 'A labyrinth of structures fills the southern part of this site. Its north side holds a large rectangular plaza, and finds run from Early Nasca pottery to Spanish colonial remains.', 'teaser-card-s041:0aa03558-b60a-46d3-8a77-7dcce6f7e015:card_description', 'teaser-card-s041 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '289876b59a0ded4840976ad8ebcfd9d9a2550b579a6a522c7287b76bd2cd163b|0206836378fc673da78674cc0f9964e82836414a2bd9af3d545c21e88c92dfb6|0206836378fc673da78674cc0f9964e82836414a2bd9af3d545c21e88c92dfb6', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A labyrinth of structures fills the southern part of this site. Its north side holds a large rectangular plaza, and finds run from Early Nasca pottery to Spanish colonial remains."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "a labyrinth of structures makes up the southern part of the site [S5]; its north side holds a large rectangular plaza [S4]; finds include Early Nasca pottery [S2]; finds run to Spanish colonial remains [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A labyrinth of structures fills the southern part of this site (Tambo Viejo, Acarí Valley, Peru). [SUPPORTED: https://revistas.pucp.edu.pe/index.php/boletindearqueologia/article/download/29942/27269]; Its north side holds a plaza (the main plaza, with the structures to its south). [SUPPORTED: https://revistas.pucp.edu.pe/index.php/boletindearqueologia/article/download/29942/27269]; The plaza on the north side is large and rectangular. [UNVERIFIABLE, no proving quote: None]; The finds at the site run back to Early Nasca pottery. [SUPPORTED: https://zenodo.org/records/1311229/files/AI1901.pdf]; The finds at the site run up to Spanish colonial remains. [SUPPORTED: https://api.crossref.org/works/10.15381/arqueolsoc.2012n24.e12349]"}]'::jsonb),
    ('0ac27bb1-9767-4302-bcfc-0480349aaf1b'::uuid, 'card_description', 'In Phoenix Park near Dublin, a water-worn capstone thought to come from the River Liffey crowns Knockmaree Dolmen, a Neolithic cist found in 1838 when workmen removed its mound.', 'In 1838, workmen clearing away a mound found this stone tomb. Four other graves lay in the outer area, and the tomb''s water-worn capstone is thought to have come from a nearby river.', 'teaser-card-s041:0ac27bb1-9767-4302-bcfc-0480349aaf1b:card_description', 'teaser-card-s041 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'c31f42ff4eaee9e24258310d9d5cbe92fb3c7beecb16e8a75e87c6f20555ca16|999a1d73ad4014313edcdd1be59a7fcaaed9ad012249f2aaaf231af1f469dd79|999a1d73ad4014313edcdd1be59a7fcaaed9ad012249f2aaaf231af1f469dd79', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "In 1838, workmen clearing away a mound found this stone tomb. Four other graves lay in the outer area, and the tomb''s water-worn capstone is thought to have come from a nearby river."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-001 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the tomb was found in 1838 [S5]; workmen removing a mound found it [S5]; it is a stone tomb [S2, S3, S6]; four other graves (cists) were found in the outer area [S6]; the capstone is water-worn [S4]; the capstone is thought to have come from a nearby river [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-002 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Workmen clearing away a mound found this stone tomb (Knockmaree, Phoenix Park, Dublin). [SUPPORTED: https://archive.org/download/proceedingsofroy01roya/proceedingsofroy01roya_djvu.txt]; The tomb is a stone tomb (a stone cist). [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=55192]; The tomb was found in 1838. [SUPPORTED: https://archive.org/download/proceedingsofroy01roya/proceedingsofroy01roya_djvu.txt]; Four other graves lay in the outer area of the mound. [SUPPORTED: https://archive.org/download/proceedingsofroy01roya/proceedingsofroy01roya_djvu.txt]; The tomb has a capstone (covering stone). [SUPPORTED: https://archive.org/download/proceedingsofroy01roya/proceedingsofroy01roya_djvu.txt]; The tomb''s capstone is water-worn. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=55192]; The capstone is thought to have come from a nearby river. [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=55192]"}]'::jsonb),
    ('0ed79845-f651-4c52-85cd-7f96bab43d4e'::uuid, 'card_description', 'Four tall slabs, 1.8 to 3 meters high, run east and west: Eightercua Stone Row, thought to date from around 1700 BC and by tradition the burial place of Scéine, wife of Amergin mac Míled.', 'Tradition says Scéine, wife of Amergin, was buried here. Four tall slabs, 1.8 to 3 metres high, run east and west, and from one stone a slab runs south, perhaps part of a tomb chamber.', 'teaser-card-s041:0ed79845-f651-4c52-85cd-7f96bab43d4e:card_description', 'teaser-card-s041 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '1f4ffaeda7a3d4b41f810dcddf32bc53532e4fa567172324c45949d4f0f2bc40|b3f660787718a00f99a0c2683597fd71b287091eb31c2df4ad3abe08331d0eb4|b3f660787718a00f99a0c2683597fd71b287091eb31c2df4ad3abe08331d0eb4', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Tradition says Scéine, wife of Amergin, was buried here. Four tall slabs, 1.8 to 3 metres high, run east and west, and from one stone a slab runs south, perhaps part of a tomb chamber."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-001 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "by tradition, Sceine is buried here [S1]; Sceine was the wife of Amergin [S1]; the site has four tall slabs [S2]; the slabs are 1.8 to 3 metres high [S2]; the slabs run east and west [S2]; from one stone a slab runs south [S3]; that slab could be part of a tomb chamber [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-001 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Tradition says Scéine, wife of Amergin, was buried here [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=3230]; Four tall slabs stand here [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=3230]; The slabs are from 1.8 metres high [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=3230]; The slabs are up to 3 metres high [SUPPORTED: https://www.discoverireland.ie/kerry/eightercua-stone-row]; The slabs run east and west [SUPPORTED: https://saintsandstones.net/stones-eightercua-journey.htm]; From one stone a slab runs south [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=3230]; That slab is perhaps part of a tomb chamber [SUPPORTED: https://www.megalithicireland.com/Eightercua%20Stone%20Row.html]"}]'::jsonb),
    ('14aacb74-9cd3-4766-b74b-4911d804c415'::uuid, 'card_description', 'Cattle from North Wales were driven along the Welsh Road to markets in South East England. Its age is not known, yet many lengths follow parish boundaries, hinting at a pre-Roman trackway.', 'A 1687 record notes money for a sick man driving beasts to London this way. Many lengths match parish or manor bounds, a sign the road was probably a trackway from before the Romans.', 'teaser-card-s041:14aacb74-9cd3-4766-b74b-4911d804c415:card_description', 'teaser-card-s041 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '75e8f0d382737448e080771a32b8a2314d162ff730a4cfceb35595910cc1d2e9|299f989d91c7996af3fbe9be39e7e428849153c642f05d286cc01e32d0940f49|299f989d91c7996af3fbe9be39e7e428849153c642f05d286cc01e32d0940f49', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite2-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A 1687 record notes money for a sick man driving beasts to London this way. Many lengths match parish or manor bounds, a sign the road was probably a trackway from before the Romans."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check2-001 (check2), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "a record from 1687 exists [S4]; it notes money given to a man who fell sick [S4]; the man was driving beasts to London along this route [S4]; many lengths of the road coincide with parish or manorial boundaries [S4]; this suggests the road was probably an ancient trackway [S4]; the trackway would date from before the Romans [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A record notes money for a sick man driving beasts to London this way. [SUPPORTED: https://www.genuki.org.uk/big/wal/Archives/NLWjournals/CattleDrovers2]; The record dates from 1687. [SUPPORTED: https://www.localdroveroads.co.uk/magpie-to-syresham/]; The record notes money. [SUPPORTED: https://www.genuki.org.uk/big/wal/Archives/NLWjournals/CattleDrovers2]; The man was sick. [SUPPORTED: https://www.genuki.org.uk/big/wal/Archives/NLWjournals/CattleDrovers2]; The man was driving beasts to London. [SUPPORTED: https://www.genuki.org.uk/big/wal/Archives/NLWjournals/CattleDrovers2]; The man was travelling this way, along the road. [SUPPORTED: https://www.localdroveroads.co.uk/magpie-to-syresham/]; Many lengths of the road match parish or manor bounds. [SUPPORTED: https://en.wikipedia.org/wiki/Drovers%27_road]; The match is a sign the road was probably a trackway from before the Romans. [SUPPORTED: https://en.wikipedia.org/wiki/Drovers%27_road]"}]'::jsonb),
    ('14bd22eb-e75c-436b-bd18-85d9b31d28fc'::uuid, 'card_description', 'Built directly over a Neolithic causewayed enclosure at Dunstable — two defensive systems separated by 3,000 years sharing the same plateau. A disused chalk quarry flanks its northwest side.', 'A disused chalk quarry has destroyed about 100 metres of this hillfort''s rampart. It rises up to 3 metres, and beneath the Iron Age fort lie traces of a Neolithic causewayed enclosure.', 'teaser-card-s041:14bd22eb-e75c-436b-bd18-85d9b31d28fc:card_description', 'teaser-card-s041 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '54e36df4ddc9ec0e97bcd5ea94832044ee02f7ecd912cc5c00716f2e43b4948b|d2a18fcc879bbda9aa7d53f98382cc2d701a32ab0936bf266d6dd38627b52014|d2a18fcc879bbda9aa7d53f98382cc2d701a32ab0936bf266d6dd38627b52014', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A disused chalk quarry has destroyed about 100 metres of this hillfort''s rampart. It rises up to 3 metres, and beneath the Iron Age fort lie traces of a Neolithic causewayed enclosure."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "a disused chalk quarry has destroyed about 100 metres of the rampart [S3]; the site is a hillfort [S1]; the rampart rises up to 3 metres [S2]; the fort is of the Iron Age [S1, S4]; traces of a Neolithic causewayed enclosure lie beneath the Iron Age fort [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-003 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A quarry has destroyed part of this hillfort''s rampart. [SUPPORTED: https://hrhsarchive.org.uk/archive/maidenbower/1232344-maidenbower]; The quarry is a chalk quarry. [SUPPORTED: https://hrhsarchive.org.uk/archive/maidenbower/1232344-maidenbower]; The quarry is disused. [SUPPORTED: https://hrhsarchive.org.uk/archive/maidenbower/1232344-maidenbower]; About 100 metres of the rampart have been destroyed. [SUPPORTED: https://hrhsarchive.org.uk/archive/maidenbower/1232344-maidenbower]; The rampart rises up to 3 metres. [SUPPORTED: https://hrhsarchive.org.uk/archive/maidenbower/1232344-maidenbower]; The fort is an Iron Age hillfort. [SUPPORTED: https://www.putnoemowsburyfriends.org.uk/maiden-bower.html]; Beneath the fort lie traces of a Neolithic causewayed enclosure. [SUPPORTED: https://hrhsarchive.org.uk/archive/maidenbower/1232344-maidenbower]"}]'::jsonb),
    ('1718bb59-ad26-498d-9803-548afc83cca7'::uuid, 'card_description', 'Inhabited since the 7th millennium BC at the foot of Mount Olympus. Continuously occupied in the Middle Neolithic (5600-4500 BC); a Bronze Age necropolis of burial mounds was established later.', 'A female figurine turned up in the Neolithic settlement here. Later, Bronze Age burial mounds held 17 people with pottery, mounds linked to the spread of peoples from the Eurasian steppes.', 'teaser-card-s041:1718bb59-ad26-498d-9803-548afc83cca7:card_description', 'teaser-card-s041 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'e2890ecbe5e47b97de0a9fbaf8c96308dcf9225314703c43dffe5d667de5caf9|73e2ffa894622b851a247d0fef15e1274d9f0eb0502b890c74077aded61ebaa7|73e2ffa894622b851a247d0fef15e1274d9f0eb0502b890c74077aded61ebaa7', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A female figurine turned up in the Neolithic settlement here. Later, Bronze Age burial mounds held 17 people with pottery, mounds linked to the spread of peoples from the Eurasian steppes."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-002 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site had a Neolithic settlement [S2]; a female figurine was found in it [S2]; later the site has Bronze Age burial mounds [S3]; the mounds held 17 people [S3]; they were buried with pottery [S3]; the mounds are linked to the spread of peoples from the Eurasian steppes [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A female figurine turned up in the Neolithic settlement here [SUPPORTED: https://leivithra.culture.gov.gr/en/park-of-leivithra/archaeological-information-building/the-macedonian-olympus-in-prehistoric-and-early-historic-era/archaeological-sites/]; there was a Neolithic settlement here [SUPPORTED: https://leivithra.culture.gov.gr/en/park-of-leivithra/archaeological-information-building/the-macedonian-olympus-in-prehistoric-and-early-historic-era/archaeological-sites/]; Later, there were Bronze Age burial mounds here [SUPPORTED: http://www.anthropology.uw.edu.pl/08/bne-08-07.pdf]; the Bronze Age burial mounds held 17 people [UNVERIFIABLE, no proving quote: None]; the people in the Bronze Age burial mounds were buried with pottery [SUPPORTED: https://www.austriaca.at/0xc1aa5572_0x002debf7.pdf]; the burial mounds are linked to the spread of peoples from the Eurasian steppes [SUPPORTED: https://leivithra.culture.gov.gr/en/park-of-leivithra/archaeological-information-building/the-macedonian-olympus-in-prehistoric-and-early-historic-era/archaeological-sites/]"}]'::jsonb),
    ('179f8253-8391-4278-b03c-c905df8f6818'::uuid, 'card_description', 'Poundbury Hill holds Neolithic, Bronze Age, and Iron Age earthworks — plus a Roman aqueduct section and a Romano-Celtic cemetery. Human use of the hill spanned from prehistory to the 8th century AD.', 'An extensive cemetery of a Roman town lies on this hill. Before the Roman graves came a large Bronze Age settlement and an Iron Age hillfort with its own late Iron Age burials.', 'teaser-card-s041:179f8253-8391-4278-b03c-c905df8f6818:card_description', 'teaser-card-s041 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '6fec0c6cbf61bdc533b8fe975aae81e6d589846c035a993946727c5f9cac65aa|ef4b69e06ab0473db8049f6359a94e13bccf89b69c900e9f71e5782bcb4ccf87|ef4b69e06ab0473db8049f6359a94e13bccf89b69c900e9f71e5782bcb4ccf87', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "An extensive cemetery of a Roman town lies on this hill. Before the Roman graves came a large Bronze Age settlement and an Iron Age hillfort with its own late Iron Age burials."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "an extensive cemetery lies at the site [S4]; the cemetery belonged to a Roman town [S4]; the site is a hill [S1]; there was a substantial (large) Bronze Age settlement at the site [S2]; there is an Iron Age hillfort at the site [S2]; the hillfort has late Iron Age burials [S2]; the Bronze Age settlement and Iron Age hillfort came before the Roman graves [S1, S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "An extensive cemetery of a Roman town lies on this hill [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/EN3604.html]; the cemetery is extensive [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO18410/]; the cemetery belonged to a Roman town [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/EN3604.html]; the cemetery lies on the hill [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO18410/]; the Roman graves came after the earlier occupation of the hill [SUPPORTED: https://heritage.dorsetcouncil.gov.uk/Monument/MDO18410/]; Before the Roman graves came a large Bronze Age settlement [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/EN3604.html]; Before the Roman graves came an Iron Age hillfort [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/EN3604.html]; the hillfort had its own late Iron Age burials [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/EN3604.html]"}]'::jsonb),
    ('17b9fc46-bc88-42a8-9606-7d7bc0dac9d1'::uuid, 'card_description', 'On high ground above the Roman Stanegate road, Pike Hill Signal Tower signalled to Gillalees Beacon and Barrock Fell. Built before the nearby walls, it later became part of Hadrian''s Wall.', 'Turned 45 degrees to Hadrian''s Wall, this tower stood offset from the wall. The tower was built before the turf or stone walls nearby, and a 2-metre fragment of its south-east wall remains.', 'teaser-card-s041:17b9fc46-bc88-42a8-9606-7d7bc0dac9d1:card_description', 'teaser-card-s041 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '6b0f751bc1aa1a5de5b4f123bcd0f21889492c2719bf8ccfc94276e78507c0bc|a16d199d4ed1c3f8f73c35383d44ee3a49e7f1e022f9743593564a766186137c|a16d199d4ed1c3f8f73c35383d44ee3a49e7f1e022f9743593564a766186137c', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Turned 45 degrees to Hadrian''s Wall, this tower stood offset from the wall. The tower was built before the turf or stone walls nearby, and a 2-metre fragment of its south-east wall remains."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the tower stood at an angle of 45 degrees to the wall [S6]; the wall is Hadrian''s Wall [S2]; the tower stood offset from the wall [S6]; the tower was built before the turf or stone walls nearby [S5]; a 2-metre fragment of its south-east wall remains [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "this tower was turned 45 degrees to Hadrian''s Wall [SUPPORTED: https://www.english-heritage.org.uk/visit/places/pike-hill-signal-tower-hadrians-wall/history/]; this tower stood offset from the wall [SUPPORTED: https://www.english-heritage.org.uk/visit/places/pike-hill-signal-tower-hadrians-wall/history/]; the tower stood at Hadrian''s Wall [SUPPORTED: https://www.english-heritage.org.uk/visit/places/pike-hill-signal-tower-hadrians-wall/history/]; The tower was built before the turf or stone walls nearby [SUPPORTED: https://www.english-heritage.org.uk/visit/places/pike-hill-signal-tower-hadrians-wall/history/]; a fragment of its south-east wall remains [SUPPORTED: https://www.english-heritage.org.uk/visit/places/pike-hill-signal-tower-hadrians-wall/history/]; the surviving fragment of the south-east wall is 2 metres long [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('186eeb54-e6a0-4370-87c6-fbcaae023a33'::uuid, 'card_description', 'On a slope above Broadsands Beach, the Broadsands Chambered Tomb now lies in a hedge bank: a Neolithic megalithic chamber that held the fragmentary remains of two adults and a child.', 'Broken bones of two adults and a child lay in this Neolithic tomb. Today it is part of a hedge bank on hilly farmland, between a beach and the tracks of a steam railway.', 'teaser-card-s041:186eeb54-e6a0-4370-87c6-fbcaae023a33:card_description', 'teaser-card-s041 (teaser-card): teaser card, 169 characters, checked PASS, web-verified VERIFIED', '39e88ab4ad0c69861dbeb0ea526bdc4e4b7c8d2b60a4520c7e6a2f287efa9cfa|11bc5ff5116e430ed90620258c6fb6957ccc8335772f7036ccebdae41c1a6341|11bc5ff5116e430ed90620258c6fb6957ccc8335772f7036ccebdae41c1a6341', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Broken bones of two adults and a child lay in this Neolithic tomb. Today it is part of a hedge bank on hilly farmland, between a beach and the tracks of a steam railway."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "fragmentary remains (broken bones) were found in the tomb [S5]; they belong to two adults and a child [S5]; it is a Neolithic tomb [S1]; today (currently) it is part of a hedge bank [S2]; it lies on hilly farmland [S2]; it lies between a beach and the tracks of a steam railway [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-004 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Broken bones of two adults and a child lay in this Neolithic tomb [SUPPORTED: https://www.geograph.org.uk/photo/2061501]; the bones were broken [SUPPORTED: https://www.galmptonandchurstonhistory.org.uk/broadsands-neolithic-chamber-tomb/]; it is a Neolithic tomb [SUPPORTED: https://www.geograph.org.uk/photo/2061501]; Today it is part of a hedge bank [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=8074]; it lies on farmland [SUPPORTED: https://www.galmptonandchurstonhistory.org.uk/broadsands-neolithic-chamber-tomb/]; the farmland is hilly [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=8074]; it lies near a beach [SUPPORTED: https://www.galmptonandchurstonhistory.org.uk/broadsands-neolithic-chamber-tomb/]; the tracks of a steam railway run nearby [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=8074]; it lies between the beach and the tracks of the steam railway [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('1b4ac17d-5b37-4459-b3c6-6722b86aa4a8'::uuid, 'card_description', 'Late 4th-century AD Byzantine settlement in the Dead Cities of the Levant. An unusually tall basilica survives; UNESCO World Heritage in 2011 as part of the Ancient Villages of Northern Syria.', 'An unusually tall basilica church stands in this early Byzantine settlement. Its columned arcades are raised high, which earned the church its nickname: Stelzenkirche, the stilted church.', 'teaser-card-s041:1b4ac17d-5b37-4459-b3c6-6722b86aa4a8:card_description', 'teaser-card-s041 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '070f96fdf8970204cfdb2f903beef850493c7f8385255e50bfc3f26059d75aff|f74cfbd1eed23d4286ed9fdc0e5bec4daa7c4f60af1e101d0afda8c4645830a5|f74cfbd1eed23d4286ed9fdc0e5bec4daa7c4f60af1e101d0afda8c4645830a5', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-001", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "An unusually tall basilica church stands in this early Byzantine settlement. Its columned arcades are raised high, which earned the church its nickname: Stelzenkirche, the stilted church."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-001 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site has an unusually tall basilica church [S2]; the site is an early Byzantine settlement [S1]; the church''s columned arcades are raised high [S2]; the raised arcades earned the church the nickname Stelzenkirche, the stilted church [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "An unusually tall basilica church stands in this settlement [SUPPORTED: https://syrian-heritage.org/kharab-shams-view-from-south-at-church-ruin-4th-6th-century-ce/]; The settlement is early Byzantine [SUPPORTED: https://dianadarke.com/tag/qalb-lozeh/]; The church has columned arcades [SUPPORTED: https://monumentsofsyria.com/places/kharab-shams-%D8%AE%D8%B1%D8%A7%D8%A8-%D8%B4%D9%85%D8%B3/]; Its columned arcades are raised high [SUPPORTED: https://archive.org/download/h-c-butler-early-churches-in-syria-fourth-to-seventh-centuries/H%20C%20Butler%20-%20Early%20Churches%20in%20Syria%20Fourth%20to%20Seventh%20Centuries_djvu.txt]; The church''s nickname is Stelzenkirche, the stilted church [SUPPORTED: https://www.anatolienportal.com/nordsyrisches-kalksteinmassiv.html]; The raised arcades earned the church its nickname [SUPPORTED: https://www.anatolienportal.com/nordsyrisches-kalksteinmassiv.html]"}]'::jsonb),
    ('1d873464-bd56-415a-984e-67026294d00c'::uuid, 'card_description', 'On a small headland of North Ronaldsay, the Iron Age Broch of Burrian gave up painted pebbles, part of an iron bell of Celtic type and a cross-slab with an ogham inscription.', 'Painted pebbles and part of an iron bell were found at this Iron Age site. These finds are of early historic or Pictish date, as is a cross-slab with ogham writing.', 'teaser-card-s041:1d873464-bd56-415a-984e-67026294d00c:card_description', 'teaser-card-s041 (teaser-card): teaser card, 164 characters, checked PASS, web-verified VERIFIED', '2b24a103d31ccfb75a6661c60aa63cdaa84a3a938b265b26d59b994fbb792b65|a106c19b9191c566547f887a5081acef3104c8253b3b06342cf42c23943f5489|a106c19b9191c566547f887a5081acef3104c8253b3b06342cf42c23943f5489', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Painted pebbles and part of an iron bell were found at this Iron Age site. These finds are of early historic or Pictish date, as is a cross-slab with ogham writing."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "painted pebbles were found at the site [S8]; part of an iron bell was found [S8]; it is an Iron Age site [S1]; these finds are of early historic or Pictish date [S7, S8]; a cross-slab was also found, of the same date [S7, S8]; the cross-slab bears ogham writing [S8]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Painted pebbles were found at this site [SUPPORTED: http://journals.socantscot.org/index.php/psas/article/download/8832/8800]; Part of an iron bell was found at this site [SUPPORTED: https://portal.historicenvironment.scot/designation/SM1427]; It is an Iron Age site [SUPPORTED: https://ferries.orkney.com/attractions/broch-of-burrian]; The painted pebbles are of early historic or Pictish date [SUPPORTED: http://journals.socantscot.org/index.php/psas/article/download/8832/8800]; The iron bell is of early historic or Pictish date [SUPPORTED: http://journals.socantscot.org/index.php/psas/article/download/8874/8842/]; A cross-slab with ogham writing was found at the site [SUPPORTED: https://ferries.orkney.com/attractions/broch-of-burrian]; The cross-slab is of early historic or Pictish date [SUPPORTED: http://journals.socantscot.org/index.php/psas/article/download/8874/8842/]"}]'::jsonb),
    ('1eb455d8-2117-4094-8c4d-76707b3a4890'::uuid, 'card_description', 'Over 1,000 megalithic stone circles across 30,000 sq km, built from the 3rd century BC to the 16th century AD. The largest concentration of stone circles on Earth.', 'Over 1,000 stone circles and burial mounds span two countries. Together the circles form the world''s largest cluster of stone circles, used for over 1,500 years.', 'teaser-card-s041:1eb455d8-2117-4094-8c4d-76707b3a4890:card_description', 'teaser-card-s041 (teaser-card): teaser card, 161 characters, checked PASS, web-verified VERIFIED', '8fd9f98766dc2a44c46fa112e853fcea8d8f851f80e37355d0f852b95f0baa23|9289360f98333c72fc476ccab236b3f08117e47480f6f020e79618d0747baa17|9289360f98333c72fc476ccab236b3f08117e47480f6f020e79618d0747baa17', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Over 1,000 stone circles and burial mounds span two countries. Together the circles form the world''s largest cluster of stone circles, used for over 1,500 years."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "there are over 1,000 stone circles and burial mounds (tumuli) [S1]; they span two countries [S1]; together they form the world''s largest concentration of stone circles [S2]; they were used for over 1,500 years [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "There are over 1,000 stone circles [SUPPORTED: https://whc.unesco.org/archive/advisory_body_evaluation/1226.pdf]; Burial mounds accompany the stone circles [SUPPORTED: https://whc.unesco.org/archive/advisory_body_evaluation/1226.pdf]; The stone circles and burial mounds span two countries [SUPPORTED: https://whc.unesco.org/archive/advisory_body_evaluation/1226.pdf]; Together the circles form the world''s largest cluster of stone circles [SUPPORTED: https://whc.unesco.org/archive/advisory_body_evaluation/1226.pdf]; The circles were used for over 1,500 years [SUPPORTED: https://whc.unesco.org/archive/advisory_body_evaluation/1226.pdf]"}]'::jsonb),
    ('1f5cb852-dcc8-440d-9931-c5968dff6cc0'::uuid, 'card_description', 'Standing 19 metres tall, Marlborough Mound is second in height only to nearby Silbury Hill. It dates from around 2400 BC, the Neolithic period, and its original purpose is unknown.', 'A Norman castle, a garden and a water tower have all used this mound. Its original purpose is unknown, and at 19 metres it is second only to nearby Silbury Hill for such a monument.', 'teaser-card-s041:1f5cb852-dcc8-440d-9931-c5968dff6cc0:card_description', 'teaser-card-s041 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '6456f159af6b4a7e27a86f69af33117fe5a9ef662310cb5a39f664b69918092c|76e06e1b8951c94f4c0cd2972680b162e6f05fbc68340c1848c51cfa3ca33e8a|76e06e1b8951c94f4c0cd2972680b162e6f05fbc68340c1848c51cfa3ca33e8a', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A Norman castle, a garden and a water tower have all used this mound. Its original purpose is unknown, and at 19 metres it is second only to nearby Silbury Hill for such a monument."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-003 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the mound served as the motte of a Norman castle [S3]; it served as a garden feature [S3]; it served as the site of a water tower [S3]; the mound''s original purpose is unknown [S5]; it is 19 metres tall [S2]; for such a monument it is second in height only to nearby Silbury Hill [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-005 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A Norman castle has used this mound [SUPPORTED: https://marlborough.news/visiting-marlborough/visiting-marlborough-within-the-town/merlin-s-mound/]; A garden has used this mound [SUPPORTED: https://marlborough.news/visiting-marlborough/visiting-marlborough-within-the-town/merlin-s-mound/]; A water tower has used this mound [SUPPORTED: https://marlborough.news/visiting-marlborough/visiting-marlborough-within-the-town/merlin-s-mound/]; Its original purpose is unknown [SUPPORTED: https://sarsen.substack.com/p/planning-to-restore-marlborough-mound]; The mound is 19 metres high [SUPPORTED: https://marlborough.news/visiting-marlborough/visiting-marlborough-within-the-town/merlin-s-mound/]; It is second only to Silbury Hill for such a monument [SUPPORTED: https://sarsen.substack.com/p/planning-to-restore-marlborough-mound]; Silbury Hill is nearby [SUPPORTED: https://rwbarber.co.uk/marlborough-mound/]"}]'::jsonb),
    ('21c68897-6da3-4cbc-abda-41e45a0c0f3c'::uuid, 'card_description', 'A Bronze Age burnt mound -- an oval heap of fire-cracked stones 14 metres across -- hidden in a park with no marker. Its purpose, whether cooking or bathing, is debated.', 'Cobbles crazed by heat fill this low oval mound of gritty black soil. Below the surface, a survey revealed three hearths, four troughs and at least seven probable pits.', 'teaser-card-s041:21c68897-6da3-4cbc-abda-41e45a0c0f3c:card_description', 'teaser-card-s041 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '57671639b8392579b463c6d8c1b7d3ef3553273b0899f3c456ceae6e4233b216|d9fbc1f8e7e15bf59c95ca3d1ce89756b3c1aed28dc2e7549422d64d4b6d27b4|d9fbc1f8e7e15bf59c95ca3d1ce89756b3c1aed28dc2e7549422d64d4b6d27b4', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Cobbles crazed by heat fill this low oval mound of gritty black soil. Below the surface, a survey revealed three hearths, four troughs and at least seven probable pits."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the mound is made of heat-crazed cobbles [S2]; the mound is low and oval [S2]; the cobbles lie in gritty black soil [S2]; a survey looked beneath the surface [S3]; the survey revealed three hearths [S3]; the survey revealed four troughs [S3]; the survey revealed at least seven probable pits [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-002 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Cobbles crazed by heat fill this mound [SUPPORTED: https://aghs.jimdofree.com/built-environment/scheduled-ancient-monument/]; The mound is low [SUPPORTED: https://aghs.jimdofree.com/built-environment/scheduled-ancient-monument/]; The mound is oval [SUPPORTED: https://aghs.jimdofree.com/built-environment/scheduled-ancient-monument/]; The mound is of gritty black soil [SUPPORTED: https://aghs.jimdofree.com/built-environment/scheduled-ancient-monument/]; Below the surface, a survey revealed three hearths [SUPPORTED: https://aghs.jimdofree.com/built-environment/scheduled-ancient-monument/]; The survey revealed four troughs [SUPPORTED: https://aghs.jimdofree.com/built-environment/scheduled-ancient-monument/]; The survey revealed at least seven probable pits [SUPPORTED: https://aghs.jimdofree.com/built-environment/scheduled-ancient-monument/]"}]'::jsonb),
    ('238793b3-c335-4dcf-8155-c9e2d4985e0d'::uuid, 'card_description', 'Bronze Age rock carvings with drainage channels all directed toward a canyon. Some carvings double as grave markers, hinting at rituals involving flowing liquid.', 'Drainage channels on three rock markings run toward a canyon. Found in 2016, the channels suggest that fluid once flowed, and similar rock markings are common across Eastern Anatolia.', 'teaser-card-s041:238793b3-c335-4dcf-8155-c9e2d4985e0d:card_description', 'teaser-card-s041 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '0a84288ff5bd5331e432736dd766a3b317162f2a660e0142049df58ef4c9f021|687fb2147a56416cf1732750963b56c50275e5d32791eb33b5dbd721d7063632|687fb2147a56416cf1732750963b56c50275e5d32791eb33b5dbd721d7063632', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Drainage channels on three rock markings run toward a canyon. Found in 2016, the channels suggest that fluid once flowed, and similar rock markings are common across Eastern Anatolia."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "there are three rock markings [S2]; the markings feature drainage channels [S2]; the channels are directed toward a canyon [S2]; they were found in 2016 [S1]; the channels suggest fluid flow [S2]; similar rock markings are common across Eastern Anatolia [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "There are three rock markings at this site [SUPPORTED: https://dergipark.org.tr/en/download/article-file/747210]; The rock markings carry drainage channels [SUPPORTED: https://dergipark.org.tr/en/download/article-file/747210]; The drainage channels run toward a canyon [SUPPORTED: https://dergipark.org.tr/en/download/article-file/747210]; The rock markings were found in 2016 [SUPPORTED: https://dergipark.org.tr/en/download/article-file/747210]; The channels suggest that fluid once flowed [SUPPORTED: https://dergipark.org.tr/en/download/article-file/747210]; Similar rock markings are common across Eastern Anatolia [SUPPORTED: https://dergipark.org.tr/en/download/article-file/747210]"}]'::jsonb),
    ('25910998-3672-4869-84cd-d737e7b8b611'::uuid, 'card_description', '150 metres from Anakena Beach — the legendary landing site of king Ariki Hotu Matu''a — several moai here still wear red stone topknots and retain carved eye sockets.', 'Easter Island''s first king, Ariki Hotu Matu''a, landed here, oral tradition says. Tradition also says he set up the first settlement here with his people, where a megalithic platform stands.', 'teaser-card-s041:25910998-3672-4869-84cd-d737e7b8b611:card_description', 'teaser-card-s041 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '8f52f57345c066e413b9167bf3a5c5bb484ea51c62679de5fa37fbb45b2df7c1|01ac4597f9e9a4a9ca0539d127b819d7f8157ece520cb40c8dcf92792f96fae8|01ac4597f9e9a4a9ca0539d127b819d7f8157ece520cb40c8dcf92792f96fae8', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Easter Island''s first king, Ariki Hotu Matu''a, landed here, oral tradition says. Tradition also says he set up the first settlement here with his people, where a megalithic platform stands."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site is on Easter Island [S1]; Ariki Hotu Matu''a was the island''s first king [S3]; according to oral tradition he landed here [S3]; according to tradition he established the first settlement here with his people [S3]; a megalithic platform stands here [S1]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-006 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Oral tradition says Ariki Hotu Matu''a landed here [SUPPORTED: https://tapestry.cyark.org/content/rapanui/transcripts]; Hotu Matu''a was Easter Island''s first king (ariki) [SUPPORTED: https://tapestry.cyark.org/content/rapanui/transcripts]; Tradition says he set up the first settlement here [SUPPORTED: https://www.easterislandfoundation.org/about-3-2]; Tradition says he set it up with his people [SUPPORTED: https://en.wikipedia.org/wiki/Anakena]; A megalithic platform stands here [SUPPORTED: https://imaginarapanui.com/en/easter-island-sightseeing/easter-island-archaeology/ahu-nau-nau/]"}]'::jsonb),
    ('27226cef-1c90-46cc-ac31-6b568c7f6c8a'::uuid, 'card_description', 'Duropolis in Dorset is believed to be Britain''s first planned town. Remains of 16 Iron Age roundhouses were dug up, and animal skeletons may hint at a belief in hybrid-animal monster myths.', 'Animal skeletons here suggest Iron Age people may have believed in hybrid monsters. A survey shows at least 150 roundhouses in a town believed to be the first planned one in Britain.', 'teaser-card-s041:27226cef-1c90-46cc-ac31-6b568c7f6c8a:card_description', 'teaser-card-s041 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', 'af0a1a52c69a2a17afe5cf8124313fa196e218e1738b0029671452c114d7f2fb|b7a5e742d022868231d8f86692c7a66cbf5d3d24a6329a66643e03377da0d6f3|b7a5e742d022868231d8f86692c7a66cbf5d3d24a6329a66643e03377da0d6f3', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Animal skeletons here suggest Iron Age people may have believed in hybrid monsters. A survey shows at least 150 roundhouses in a town believed to be the first planned one in Britain."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "animal skeletons were found at the site [S6]; they suggest the Iron Age people may have believed in hybrid-animal monsters [S6]; a survey shows at least 150 roundhouses [S5]; the site is believed to be the first planned town in Britain [S1]; the people were of the Iron Age [S2, S6]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Animal skeletons here suggest people may have believed in hybrid monsters. [SUPPORTED: https://www.ibtimes.co.uk/prehistoric-town-duropolis-discovered-dorset-one-britains-largest-iron-age-settlements-1510613]; The people who may have believed in hybrid monsters were Iron Age people. [SUPPORTED: https://www.livescience.com/51593-duropolis-hybrid-animals.html]; A survey shows at least 150 roundhouses here. [SUPPORTED: https://www.ibtimes.co.uk/prehistoric-town-duropolis-discovered-dorset-one-britains-largest-iron-age-settlements-1510613]; The site is a town. [SUPPORTED: https://www.ibtimes.co.uk/prehistoric-town-duropolis-discovered-dorset-one-britains-largest-iron-age-settlements-1510613]; The town is believed to be the first planned town in Britain. [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('2a486734-8365-4c1e-93b2-f1c2f092789e'::uuid, 'card_description', 'Occupied from the 6th millennium BC, Arslantepe peaked in the Late Chalcolithic. Its palace complex is one of the earliest known — contemporary with the earliest urbanism in southern Mesopotamia.', 'The world''s earliest known swords were dug out of this mound. Its palace of the 4th millennium BC shows an early state taking shape, with a system of officials older than writing.', 'teaser-card-s041:2a486734-8365-4c1e-93b2-f1c2f092789e:card_description', 'teaser-card-s041 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '74d94383861b956b979bf423c1edbe8c78811aac54e55a0c7c843ba74d1bd387|e4f751bafc8125e82ee9101e3c0d6b72cc8ec86481cee96460a842a66834a728|e4f751bafc8125e82ee9101e3c0d6b72cc8ec86481cee96460a842a66834a728', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "The world''s earliest known swords were dug out of this mound. Its palace of the 4th millennium BC shows an early state taking shape, with a system of officials older than writing."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the world''s earliest known swords were excavated here [S3]; the site is a mound (tell) [S1]; it has a palace of the 4th millennium BC [S2]; the palace shows evidence of early state formation [S2]; it shows a bureaucratic system older than writing [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "The world''s earliest known swords were dug out of this site. [SUPPORTED: https://www.anatolianarchaeology.net/the-worlds-oldest-swords-and-the-birth-of-warfare-at-arslantepe/]; The site is a mound. [SUPPORTED: https://www.anatolianarchaeology.net/the-worlds-oldest-swords-and-the-birth-of-warfare-at-arslantepe/]; Its palace dates to the 4th millennium BC. [SUPPORTED: https://www.uniroma1.it/it/notizia/arslantepe-alle-origini-delle-prime-forme-di-stato-inaugurato-il-nuovo-percorso-del-sito]; The palace shows an early state taking shape. [SUPPORTED: https://www.uniroma1.it/it/notizia/arslantepe-alle-origini-delle-prime-forme-di-stato-inaugurato-il-nuovo-percorso-del-sito]; The palace had a system of officials older than writing. [SUPPORTED: https://www.uniroma1.it/it/notizia/arslantepe-alle-origini-delle-prime-forme-di-stato-inaugurato-il-nuovo-percorso-del-sito]"}]'::jsonb),
    ('2bb3d2fe-62b3-4d3f-b12f-e9bdee25f150'::uuid, 'card_description', 'Lower Paleolithic cave site at 1,600 metres in the Caucasus highlands. Acheulean handaxes from 40,000-25,000 years ago at Kudaro push early human presence deep into the high mountains of the region.', 'Remains of a cave bear turned up in this highland complex of Old Stone Age caves. One layer dates to 360,000 years ago, and the caves held tools such as choppers and side scrapers.', 'teaser-card-s041:2bb3d2fe-62b3-4d3f-b12f-e9bdee25f150:card_description', 'teaser-card-s041 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '42b512d3daeb2c7d76a80ed9a98cf998bf8b64aae6af17ad7839b16730b29b05|a90ea75a73ac3427f6c1dfa27ec92b8d15ff68382f356e92fdc72f76c2a25c4b|a90ea75a73ac3427f6c1dfa27ec92b8d15ff68382f356e92fdc72f76c2a25c4b', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Remains of a cave bear turned up in this highland complex of Old Stone Age caves. One layer dates to 360,000 years ago, and the caves held tools such as choppers and side scrapers."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "remains of a cave bear were found here [S4]; the site is a complex of caves [S1]; the caves are in the highlands [S1]; the caves are Old Stone Age (Paleolithic) sites [S1]; one layer is dated to 360,000 years ago [S3]; the caves held choppers [S2]; the caves held side scrapers [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Remains of a cave bear turned up in this complex. [SUPPORTED: https://www.sci.news/paleontology/ursus-kudarensis-genome-09392.html]; The complex is in the highlands. [SUPPORTED: https://www.zin.ru/journals/trudyzin/doc/vol_315_3/tz_315_3_baryshnikov.pdf]; The complex is made up of caves. [SUPPORTED: https://www.zin.ru/journals/trudyzin/doc/vol_315_3/tz_315_3_baryshnikov.pdf]; The caves are Old Stone Age sites. [SUPPORTED: https://www.zin.ru/journals/trudyzin/doc/vol_315_3/tz_315_3_baryshnikov.pdf]; One layer dates to 360,000 years ago. [SUPPORTED: https://www.zin.ru/journals/trudyzin/doc/vol_315_3/tz_315_3_baryshnikov.pdf]; The caves held choppers. [SUPPORTED: https://paleoanthro.net/media/journal/content/PA20080107.pdf]; The caves held side scrapers. [SUPPORTED: https://paleoanthro.net/media/journal/content/PA20080107.pdf]"}]'::jsonb),
    ('2c437fa8-96cf-4451-b949-7e5c09889802'::uuid, 'card_description', NULL, 'Sand covered this pyramid until a local landowner found it in 1923. The pyramid''s walls show fishing nets with fish, seabirds, waves and diamond patterns, all in relief.', 'teaser-card-s041:2c437fa8-96cf-4451-b949-7e5c09889802:card_description', 'teaser-card-s041 (teaser-card): teaser card, 169 characters, checked PASS, web-verified VERIFIED', 'b280e0b936dc1f84fe9fc770d01df36edeec70bb621e4a3205fafefce64b1126|54cb40b6988dd10ddecc11ec0c52c64896586aaebcbf1959aadc94568d9a695d|54cb40b6988dd10ddecc11ec0c52c64896586aaebcbf1959aadc94568d9a695d', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-004", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Sand covered this pyramid until a local landowner found it in 1923. The pyramid''s walls show fishing nets with fish, seabirds, waves and diamond patterns, all in relief."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-004 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the pyramid was buried under sand [S4]; a local landowner discovered it [S4]; it was discovered in 1923 [S4]; the site is a pyramid [S2]; its walls show fishing nets with fish [S3]; its walls show seabirds [S3]; its walls show waves [S3]; its walls show diamond patterns [S3]; the decorations are in relief [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-007 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Sand covered this pyramid until it was found. [SUPPORTED: https://www.lonelyplanet.com/points-of-interest/huaca-esmeralda/1165471]; A local landowner found it. [SUPPORTED: https://www.lonelyplanet.com/points-of-interest/huaca-esmeralda/1165471]; It was found in 1923. [SUPPORTED: https://www.roughguides.com/peru/trujillo-and-the-north/trujillo/]; The site is a pyramid. [SUPPORTED: https://www.roughguides.com/peru/trujillo-and-the-north/trujillo/]; The pyramid''s walls show fishing nets with fish. [SUPPORTED: https://www.roughguides.com/peru/trujillo-and-the-north/trujillo/]; The pyramid''s walls show seabirds. [SUPPORTED: https://www.lonelyplanet.com/points-of-interest/huaca-esmeralda/1165471]; The pyramid''s walls show waves. [SUPPORTED: https://www.lonelyplanet.com/points-of-interest/huaca-esmeralda/1165471]; The pyramid''s walls show diamond patterns. [SUPPORTED: http://www.divinaprovidencia.org/Las%20Huacas/Huacas.htm]; All these designs are in relief. [SUPPORTED: https://www.roughguides.com/peru/trujillo-and-the-north/trujillo/]"}]'::jsonb),
    ('2cea8e97-21f2-4d79-95f3-c00ef69985eb'::uuid, 'card_description', 'A curvilinear La Tène style design covers the top half of the Turoe Stone in County Galway, probably from about 100 BC to AD 100. Its religious or ceremonial purposes are lost in time.', 'Swirls cover the top half of this granite stone in one unbroken design. The design is like one on the Castlestrange Stone, but this stone''s religious or ceremonial purposes are lost in time.', 'teaser-card-s041:2cea8e97-21f2-4d79-95f3-c00ef69985eb:card_description', 'teaser-card-s041 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', 'c1cd758ad4762e95d27228bb6bfc091537814e038c1507258e48ca07a951f403|429aaf27bcfb2f05579f0446d5c4d03a651647872ea921abb11e49bf8b9e35c1|429aaf27bcfb2f05579f0446d5c4d03a651647872ea921abb11e49bf8b9e35c1', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Swirls cover the top half of this granite stone in one unbroken design. The design is like one on the Castlestrange Stone, but this stone''s religious or ceremonial purposes are lost in time."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the stone is made of granite [S1]; a curvilinear design covers the top half of the stone [S4]; the design is continuous [S4]; the design is similar to one on the Castlestrange Stone [S4]; the stone had religious or ceremonial purposes [S5]; those purposes are lost in time [S5]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Swirls cover the top half of this stone [SUPPORTED: https://heritageireland.ie/unguided-sites/turoe-stone/]; The stone is granite [SUPPORTED: http://www.visual-arts-cork.com/irish-sculpture/turoe-stone.htm]; The swirls form one unbroken design [SUPPORTED: http://www.visual-arts-cork.com/irish-sculpture/turoe-stone.htm]; The design is like one on the Castlestrange Stone [SUPPORTED: http://www.carrowkeel.com/sites/misc/turoe.html]; The stone had religious or ceremonial purposes [SUPPORTED: http://www.visual-arts-cork.com/irish-sculpture/turoe-stone.htm]; The stone''s religious or ceremonial purposes are lost in time [SUPPORTED: http://www.visual-arts-cork.com/irish-sculpture/turoe-stone.htm]"}]'::jsonb),
    ('2d786593-6e3f-40a9-8113-8012f6c2d35e'::uuid, 'card_description', 'At Delphi, a pillar once meant for a portrait of King Perseus became the Monument of Aemilius Paullus, crowned by a bronze equestrian statue and a frieze of the Battle of Pydna.', 'A pillar begun for a portrait of King Perseus became a monument to his defeat. Over 9 meters high, the pillar carried a bronze statue of a rider, ringed by a frieze of the Battle of Pydna.', 'teaser-card-s041:2d786593-6e3f-40a9-8113-8012f6c2d35e:card_description', 'teaser-card-s041 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '8af204d80ba925d0980b56d5b32f42cc1b5a4b29f0b83107994d406beeee3027|3a9462696398009a744d3e72f823b2036ff53360631f268b5fc085c8fa75039a|3a9462696398009a744d3e72f823b2036ff53360631f268b5fc085c8fa75039a', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-005", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A pillar begun for a portrait of King Perseus became a monument to his defeat. Over 9 meters high, the pillar carried a bronze statue of a rider, ringed by a frieze of the Battle of Pydna."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the pillar was begun as a base for a portrait of King Perseus [S2]; the pillar became part of a monument commemorating the defeat of Perseus [S1, S2]; the pillar is over 9 meters high [S3]; the pillar carried a bronze statue of a rider [S3]; a frieze depicting the Battle of Pydna runs around the pillar [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A pillar begun for a portrait of King Perseus became a monument to his defeat. [SUPPORTED: https://delphi.culture.gr/zwforos-mnimeiou-aimiliou-pavlou/]; The pillar was begun for a portrait (statue) of King Perseus. [SUPPORTED: https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Plutarch/Lives/Aemilius*.html]; The pillar is over 9 meters high. [SUPPORTED: https://lesdioscures.com/paul-emile/]; The pillar carried a bronze statue of a rider. [SUPPORTED: http://davidgibbins.com/journal/2013/11/14/total-war-rome-the-triumph-of-aemilius-paullus]; The pillar was ringed by a frieze (running round its four faces). [SUPPORTED: https://didierlaroche.wixsite.com/delphes/sd-418-pilier-de-paul-emile]; The frieze shows the Battle of Pydna. [SUPPORTED: https://delphi.culture.gr/zwforos-mnimeiou-aimiliou-pavlou/]"}]'::jsonb),
    ('2e2617fe-2aa6-48ba-b8f1-4b3725e25e8d'::uuid, 'card_description', 'On a cliff-top promontory 20 metres above the sea, the Broch of Borwick keeps walls 3.5 to 5 metres thick. Its finds included combs, a small whale vertebra cup and a stone gaming piece.', 'A whale vertebra cup and a stone gaming piece were found at this Iron Age tower. It stands on a cliff-top headland above the sea, where erosion has destroyed the tower''s western half.', 'teaser-card-s041:2e2617fe-2aa6-48ba-b8f1-4b3725e25e8d:card_description', 'teaser-card-s041 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '15172b21af3353822d51a862c1e9614aa15665dd01a239cb27e162b3f4f4c873|23413a78e4d443b41b4595ed3ee5d9909ca521574cbce74d3fc74e6a8a0c54f5|23413a78e4d443b41b4595ed3ee5d9909ca521574cbce74d3fc74e6a8a0c54f5', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A whale vertebra cup and a stone gaming piece were found at this Iron Age tower. It stands on a cliff-top headland above the sea, where erosion has destroyed the tower''s western half."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "a whale vertebra cup was found at the site [S7]; a stone gaming piece was found at the site [S7]; the site is an Iron Age broch (tower) [S1]; it stands on a cliff-top promontory [S2]; the promontory is above the sea [S2]; erosion has destroyed the western half [S5]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A whale vertebra cup was found at this tower [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/SC2845.html]; A stone gaming piece was found at this tower [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/SC2845.html]; The site is an Iron Age tower [SUPPORTED: https://archaeologyorkney.com/2025/04/30/broch-of-borwick/]; It stands on a cliff-top headland above the sea [SUPPORTED: https://archaeologyorkney.com/2025/04/30/broch-of-borwick/]; There is a cliff below the tower, above the sea [SUPPORTED: https://archaeologyorkney.com/2025/04/30/broch-of-borwick/]; The tower''s western half has been destroyed [SUPPORTED: https://archaeologyorkney.com/2025/04/30/broch-of-borwick/]; Erosion destroyed the tower''s western half [SUPPORTED: http://hillforts.arch.ox.ac.uk/records/SC2845.html]"}]'::jsonb),
    ('31490608-0d55-49b1-843b-b983ed37ae64'::uuid, 'card_description', 'On the hilltop of Sancreed Beacon, in Cornwall''s Penwith peninsula, lie stone cists and Bronze Age burial mounds, while the western slope keeps the remains of a Bronze Age hut.', 'Stone box graves and burial mounds crown this Bronze Age hilltop. An Iron Age village lies 1 mile southwest and a hill fort half a mile away, amid remains as old as Neolithic times.', 'teaser-card-s041:31490608-0d55-49b1-843b-b983ed37ae64:card_description', 'teaser-card-s041 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'a3c8f8b5babb795cd6dc471e5ef2ef088d7c9ec67b4ee3fbd42c8c39a45dcf65|ec3494cb1c28f8d648ef26f280723e6ae012e4f529ae782bced212c2dd81491d|ec3494cb1c28f8d648ef26f280723e6ae012e4f529ae782bced212c2dd81491d', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Stone box graves and burial mounds crown this Bronze Age hilltop. An Iron Age village lies 1 mile southwest and a hill fort half a mile away, amid remains as old as Neolithic times."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "stone cists (stone box graves) are on top of the hill [S2]; burial mounds are on top of the hill [S2]; it is a Bronze Age site on a hill [S1, S2]; an Iron Age village lies 1 mile to the southwest [S3]; a hill fort lies half a mile away [S3]; evidence in the vicinity dates as far back as Neolithic times [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-008 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Stone box graves (cists) crown this hilltop. [SUPPORTED: http://www.cornwallheritagetrust.org/wp-content/uploads/2015/06/Sancreed-Beacon.pdf]; Burial mounds crown this hilltop. [SUPPORTED: http://www.cornwallheritagetrust.org/wp-content/uploads/2015/06/Sancreed-Beacon.pdf]; It is a Bronze Age hilltop. [SUPPORTED: http://www.cornwallheritagetrust.org/wp-content/uploads/2015/06/Sancreed-Beacon.pdf]; An Iron Age village lies 1 mile southwest. [SUPPORTED: http://www.cornwallheritagetrust.org/wp-content/uploads/2015/06/Sancreed-Beacon.pdf]; A hill fort lies half a mile away. [SUPPORTED: http://www.cornwallheritagetrust.org/wp-content/uploads/2015/06/Sancreed-Beacon.pdf]; It lies amid remains as old as Neolithic times. [SUPPORTED: http://www.cornwallheritagetrust.org/wp-content/uploads/2015/06/Sancreed-Beacon.pdf]"}]'::jsonb),
    ('3208b51e-e296-4c28-af06-55f6869e507c'::uuid, 'card_description', 'A 35-metre section of Hadrian''s Wall showing where builders switched from Broad Wall to Narrow Wall mid-construction. The join is clearly visible in the stonework.', 'A narrow wall stands on foundations that were laid for a broad one. The surviving stretch is 35 metres long, and its eastern part is built as Broad Wall, 10 Roman feet wide.', 'teaser-card-s041:3208b51e-e296-4c28-af06-55f6869e507c:card_description', 'teaser-card-s041 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', '8fb44adabf2a3c8168a2297414d2766e7ebadc82880f47b24625df33c5a4892e|90c9cf1aa0a6c6939bb626010a861f5f47dff08b3b1bcd265ab12a2b43cf89ff|90c9cf1aa0a6c6939bb626010a861f5f47dff08b3b1bcd265ab12a2b43cf89ff', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A narrow wall stands on foundations that were laid for a broad one. The surviving stretch is 35 metres long, and its eastern part is built as Broad Wall, 10 Roman feet wide."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-002 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "a narrow-gauge wall stands on foundations laid for a broad wall [S3]; the surviving stretch is 35 metres long [S2]; the eastern part is built as Broad Wall [S3]; the Broad Wall part is 10 Roman feet wide [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A narrow wall stands on foundations that were laid for a broad one [SUPPORTED: https://www.english-heritage.org.uk/visit/places/planetrees-roman-wall-hadrians-wall/history/]; The broad foundations were laid before the wall was narrowed [SUPPORTED: https://www.english-heritage.org.uk/visit/places/planetrees-roman-wall-hadrians-wall/history/]; The surviving stretch is 35 metres long [SUPPORTED: https://www.english-heritage.org.uk/visit/places/planetrees-roman-wall-hadrians-wall/history/]; The eastern part of the stretch is built as Broad Wall [SUPPORTED: https://www.english-heritage.org.uk/visit/places/planetrees-roman-wall-hadrians-wall/history/]; The Broad Wall is 10 Roman feet wide [SUPPORTED: https://www.english-heritage.org.uk/visit/places/planetrees-roman-wall-hadrians-wall/history/]"}]'::jsonb),
    ('32f8606a-075b-4e6c-afae-427a49ef9df4'::uuid, 'card_description', 'Discovered in 1822 and then dismantled, Smythe''s Megalith was a long barrow of earth and sarsen stones near Aylesford in Kent, where human remains were laid in its stone chamber.', 'Taken apart the moment it was found, this monument held human remains. They lay in a stone chamber, and the monument used at least five local sarsen stones, in a style of the River Medway.', 'teaser-card-s041:32f8606a-075b-4e6c-afae-427a49ef9df4:card_description', 'teaser-card-s041 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '8951131e10153345500d665025e6cbc40f0d7ba812af7e44dc86c94950ab2518|6209d9d56ace69fe437fc587301c7cd36f22f416c7d89b380de923857a89c55e|6209d9d56ace69fe437fc587301c7cd36f22f416c7d89b380de923857a89c55e', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Taken apart the moment it was found, this monument held human remains. They lay in a stone chamber, and the monument used at least five local sarsen stones, in a style of the River Medway."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the monument was dismantled at the time it was discovered [S2]; human remains were placed in the monument [S4]; the remains lay in a stone chamber [S3, S4]; the monument was built with at least five local sarsen stones [S3]; it belongs to a regional style of the River Medway area [S6]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-003 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "This monument was taken apart the moment it was found [SUPPORTED: https://www.kentarchaeology.org.uk/arch-cant/vol/61/smythes-megalith]; The monument held human remains [SUPPORTED: https://www.kentarchaeology.org.uk/arch-cant/vol/61/smythes-megalith]; The human remains lay in a stone chamber [SUPPORTED: https://www.kentarchaeology.org.uk/arch-cant/vol/61/smythes-megalith]; The monument used at least five stones (four chamber stones and a flat floor stone) [SUPPORTED: https://www.kentarchaeology.org.uk/arch-cant/vol/61/smythes-megalith]; The stones were sarsens [SUPPORTED: https://www.megalithic.co.uk/article.php?sid=10566]; The sarsen stones were local [SUPPORTED: https://www.kentarchaeology.org.uk/arch-cant/vol/61/smythes-megalith]; The monument was built in a style of the River Medway [SUPPORTED: https://static1.squarespace.com/static/65df7835178a9d2b20f8d501/t/6758114f8be5f93dd065d7f7/1733824849204/archaeologia-cantiana_063-04_kentish_megalith_types.pdf]"}]'::jsonb),
    ('331d86ab-697d-411b-b61b-6af1875c7e1c'::uuid, 'card_description', 'In 2018 a farmer in Huelva set out to plant avocados. The survey that followed has so far revealed 526 standing stones at La Torre-La Janera Megalithic Site, upright or lying on the surface.', 'A farmer planning to grow avocados led to this find in 2018. So far the survey has revealed 526 standing stones, some still standing and some lying on the surface.', 'teaser-card-s041:331d86ab-697d-411b-b61b-6af1875c7e1c:card_description', 'teaser-card-s041 (teaser-card): teaser card, 163 characters, checked PASS, web-verified VERIFIED', 'beb554f7398b55a69d144922899a6aae34ea512df52cf7bc8659a01bae4d6d6f|76f960892d3daf6fcab9445de6b46eb417de650ab16c915ae073f12a18e74dfb|76f960892d3daf6fcab9445de6b46eb417de650ab16c915ae073f12a18e74dfb', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-005", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A farmer planning to grow avocados led to this find in 2018. So far the survey has revealed 526 standing stones, some still standing and some lying on the surface."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-005 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the site was discovered in 2018 [S2]; the discovery came about when a farmer planned to cultivate avocados on the land [S2]; so far the survey has revealed 526 standing stones [S4]; the stones are either still standing or lying on the surface [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A farmer planning to grow avocados led to this find. [SUPPORTED: https://www.livescience.com/neolithic-stone-complex-discovered-spain]; The find was made in 2018. [SUPPORTED: https://www.livescience.com/neolithic-stone-complex-discovered-spain]; So far the survey has revealed 526 standing stones. [SUPPORTED: https://portalcomunicacion.uah.es/diario-digital/actualidad/una-profesora-de-la-uah-participa-en-el-descubrimiento-de-la-mayor-concentracion-megalitica-de-espana/]; Some of the standing stones are still standing. [SUPPORTED: https://portalcomunicacion.uah.es/diario-digital/actualidad/una-profesora-de-la-uah-participa-en-el-descubrimiento-de-la-mayor-concentracion-megalitica-de-espana/]; Some of the standing stones are lying on the surface. [SUPPORTED: https://portalcomunicacion.uah.es/diario-digital/actualidad/una-profesora-de-la-uah-participa-en-el-descubrimiento-de-la-mayor-concentracion-megalitica-de-espana/]"}]'::jsonb),
    ('353f7688-f230-41ef-a181-8bd9341448cf'::uuid, 'card_description', 'On the highest point of Bodmin Moor, 1,378 feet up, the summit pile of the Brown Willy Cairns has never been excavated. Folklore suggests an ancient Cornish king may lie entombed underneath.', 'Folklore says an ancient Cornish king may lie buried under this rock pile. The man-made cairn has never been excavated, and it sits beside a survey station on a summit 1,378 feet up.', 'teaser-card-s041:353f7688-f230-41ef-a181-8bd9341448cf:card_description', 'teaser-card-s041 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '3263c7ca93b5f919137f58e407a9085ec75f7e0951ad341f96fc64fdc5fe9c54|1f12d838cb8a7a97b9bea26bb324c768c8e8634858c7be39c6f742efecde645d|1f12d838cb8a7a97b9bea26bb324c768c8e8634858c7be39c6f742efecde645d', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-006", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Folklore says an ancient Cornish king may lie buried under this rock pile. The man-made cairn has never been excavated, and it sits beside a survey station on a summit 1,378 feet up."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "folklore suggests an ancient Cornish king may lie buried under the rock pile [S3]; the cairn is man-made [S2]; the cairn has never been excavated [S3]; it sits beside a survey (triangulation) station [S2]; it is on a summit 1,378 feet above sea level [S1, S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-009 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Folklore says an ancient Cornish king may lie buried under this rock pile. [SUPPORTED: https://heritageaction.wordpress.com/2022/03/29/brown-willy-cornwalls-highest-hill/]; The cairn is man-made. [SUPPORTED: https://www.theguardian.com/uk-news/2016/sep/13/brown-willy-cornwalls-highest-point-up-for-sale-at-28m]; The cairn has never been excavated. [SUPPORTED: https://heritageaction.wordpress.com/2022/03/29/brown-willy-cornwalls-highest-hill/]; The cairn sits beside a survey station. [SUPPORTED: https://www.geograph.org.uk/photo/2818731]; The cairn sits on a summit. [SUPPORTED: https://www.geograph.org.uk/photo/2818731]; The summit is 1,378 feet up. [SUPPORTED: https://www.theguardian.com/uk-news/2016/sep/13/brown-willy-cornwalls-highest-point-up-for-sale-at-28m]"}]'::jsonb),
    ('384133aa-dc2d-4f86-9f20-e53c98e5c5be'::uuid, 'card_description', 'First noted by Father Carvalho Costa in 1712, the Roman Dam of Pego da Moura in Grândola is a small buttress dam built almost entirely of opus incertum, braced by six downstream buttresses.', 'Father Carvalho Costa first noted this small Roman wall in 1712. Built in two phases, the wall still has six buttresses on its downstream side, yet a brief study of it came much later.', 'teaser-card-s041:384133aa-dc2d-4f86-9f20-e53c98e5c5be:card_description', 'teaser-card-s041 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '6174ce707f8cb296a7f9603a7b563fb80e9da447cc430d4a2a4ade8278f0714b|e7d7020ca7f97c53db820cc73f446ae4d9e71e4091de95351a71d6b57485f9b2|e7d7020ca7f97c53db820cc73f446ae4d9e71e4091de95351a71d6b57485f9b2', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-006", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Father Carvalho Costa first noted this small Roman wall in 1712. Built in two phases, the wall still has six buttresses on its downstream side, yet a brief study of it came much later."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Father Carvalho Costa first noted the structure [S7]; he noted it in 1712 [S7]; it is small [S1]; it is Roman [S2]; it is a wall [S3]; it was built in two phases [S3]; it has six buttresses on its downstream side today [S5]; a brief study of it was made much later than 1712 [S8]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Father Carvalho Costa first noted this small Roman wall in 1712. [SUPPORTED: https://www.visitgrandola.com/conhecer/patrimonio/romano/poi/barragem-romana-do-pego-da-moura]; The noter was a Father (priest), Carvalho Costa. [SUPPORTED: https://www.visitgrandola.com/conhecer/patrimonio/romano/poi/barragem-romana-do-pego-da-moura]; The wall is Roman. [SUPPORTED: https://www.visitgrandola.com/conhecer/patrimonio/romano/poi/barragem-romana-do-pego-da-moura]; The Roman wall is small. [SUPPORTED: https://www.visitgrandola.com/conhecer/museus/sitios-romanos]; The wall was built in two phases. [SUPPORTED: http://redepatrimoniofids.amrs.pt/barragem-romana-do-pego-da-moura/]; The wall still has six buttresses on its downstream side. [SUPPORTED: http://redepatrimoniofids.amrs.pt/barragem-romana-do-pego-da-moura/]; The six buttresses are still there today. [SUPPORTED: https://www.visitgrandola.com/conhecer/patrimonio/romano/poi/barragem-romana-do-pego-da-moura]; A brief study of it came much later (than 1712). [SUPPORTED: https://www.visitgrandola.com/conhecer/patrimonio/romano/poi/barragem-romana-do-pego-da-moura]"}]'::jsonb),
    ('3af2d2bf-8e21-4e12-83a7-5b1bffc3d5db'::uuid, 'card_description', 'A 3rd-millennium BC Orkney-Cromarty chambered cairn on Eday, overlooking Calf Sound. Its three separate stalled inner compartments make it a rare tripartite example of the type.', 'Two storeys make this Neolithic tomb a rare burial monument. From outside it is just a small, low, circular mound, 10 m in diameter and 60 cm high, on a gently sloping hill.', 'teaser-card-s041:3af2d2bf-8e21-4e12-83a7-5b1bffc3d5db:card_description', 'teaser-card-s041 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', '3e1e408a41cde221a92a916ec0a0f5014827e4da7f99c99512b08676d7430256|d00127aa9bc5e1d4df61196e324a23fd99103d324c9b8a7836d9a335486b9abf|d00127aa9bc5e1d4df61196e324a23fd99103d324c9b8a7836d9a335486b9abf', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-006", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Two storeys make this Neolithic tomb a rare burial monument. From outside it is just a small, low, circular mound, 10 m in diameter and 60 cm high, on a gently sloping hill."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-006 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the tomb has two storeys [S6]; being double-storied makes it a rare burial monument [S6]; it is Neolithic [S1, S4]; it is a tomb [S5, S6]; it appears as a small, low, circular mound [S7]; the mound is 10 m in diameter [S7]; the mound is 60 cm high [S7]; it stands on a gently sloping hill [S2]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Two storeys make this Neolithic tomb a rare burial monument. [SUPPORTED: https://portal.historicenvironment.scot/apex/f?p=1505%3A300%3A%3A%3A%3A%3AVIEWTYPE%2CVIEWREF%3Adesignation%2CSM1250]; The tomb has two storeys. [SUPPORTED: https://portal.historicenvironment.scot/apex/f?p=1505%3A300%3A%3A%3A%3A%3AVIEWTYPE%2CVIEWREF%3Adesignation%2CSM1250]; The tomb is Neolithic. [SUPPORTED: https://portal.historicenvironment.scot/apex/f?p=1505%3A300%3A%3A%3A%3A%3AVIEWTYPE%2CVIEWREF%3Adesignation%2CSM1250]; From outside it is just a mound. [SUPPORTED: https://portal.historicenvironment.scot/apex/f?p=1505%3A300%3A%3A%3A%3A%3AVIEWTYPE%2CVIEWREF%3Adesignation%2CSM1250]; The mound is small. [SUPPORTED: https://portal.historicenvironment.scot/apex/f?p=1505%3A300%3A%3A%3A%3A%3AVIEWTYPE%2CVIEWREF%3Adesignation%2CSM1250]; The mound is low. [SUPPORTED: https://portal.historicenvironment.scot/apex/f?p=1505%3A300%3A%3A%3A%3A%3AVIEWTYPE%2CVIEWREF%3Adesignation%2CSM1250]; The mound is circular. [SUPPORTED: https://portal.historicenvironment.scot/apex/f?p=1505%3A300%3A%3A%3A%3A%3AVIEWTYPE%2CVIEWREF%3Adesignation%2CSM1250]; The mound is 10 m in diameter. [SUPPORTED: https://portal.historicenvironment.scot/apex/f?p=1505%3A300%3A%3A%3A%3A%3AVIEWTYPE%2CVIEWREF%3Adesignation%2CSM1250]; The mound is 60 cm high. [SUPPORTED: https://portal.historicenvironment.scot/apex/f?p=1505%3A300%3A%3A%3A%3A%3AVIEWTYPE%2CVIEWREF%3Adesignation%2CSM1250]; The mound is on a gently sloping hill. [SUPPORTED: https://portal.historicenvironment.scot/apex/f?p=1505%3A300%3A%3A%3A%3A%3AVIEWTYPE%2CVIEWREF%3Adesignation%2CSM1250]"}]'::jsonb),
    ('3b348ad3-00f1-4d9a-9782-9006f4443cda'::uuid, 'card_description', 'On Exmoor, the turf-covered Bronze Age bowl barrow Alderman''s Barrow measures 24 by 22 meters and stands 1.4 meters high. In the 13th century it was called Osmunesburgh.', 'Before its current name came in 1782, this mound went by two others. The turf-covered mound served as a Bronze Age burial place and later as a boundary marker for several parishes.', 'teaser-card-s041:3b348ad3-00f1-4d9a-9782-9006f4443cda:card_description', 'teaser-card-s041 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'e8db61e295812e29b4a6cc5b3fec442d130b85291d0e71521bbe1fd940a058ff|db3acd301f2b9380405c6d70515d080564c1668a985a08137968734046dedc3c|db3acd301f2b9380405c6d70515d080564c1668a985a08137968734046dedc3c', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Before its current name came in 1782, this mound went by two others. The turf-covered mound served as a Bronze Age burial place and later as a boundary marker for several parishes."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "the mound received its current name in 1782 [S3]; before that it was known by two other names [S3]; the mound is turf-covered [S2]; it served as a Bronze Age burial place [S1]; it later served as a boundary marker for several parishes [S1]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-010 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Before its current name came in 1782, this mound went by two others. [SUPPORTED: https://www.exmoorher.co.uk/Monument/MSO6730]; Its current name (Alderman''s Barrow) came in 1782. [SUPPORTED: https://www.exmoorher.co.uk/Monument/MSO6730]; The mound is turf-covered. [SUPPORTED: https://www.exmoorher.co.uk/Monument/MSO6730]; The mound served as a Bronze Age burial place. [SUPPORTED: https://www.exmoorher.co.uk/Monument/MSO6730]; The mound later served as a boundary marker. [SUPPORTED: https://www.exmoorher.co.uk/Monument/MSO6730]; The boundary it marked was that of several parishes. [SUPPORTED: https://www.exmoorher.co.uk/Monument/MSO6730]"}]'::jsonb),
    ('4063671e-4cb4-405c-b5af-f7d0e9bd922b'::uuid, 'card_description', 'A Bronze Age site from 1000 BC overlaid by an Anglo-Saxon cemetery. Glass vessels and gold jewelry from the graves reveal far-reaching trade networks.', 'Glass objects in unusual numbers came from an Anglo-Saxon cemetery here. The chalk hill also holds an Iron Age hillfort, and a WWII radar station and the 1987 Great Storm damaged the site.', 'teaser-card-s041:4063671e-4cb4-405c-b5af-f7d0e9bd922b:card_description', 'teaser-card-s041 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'd1a35f179a3ca8dbc0a7d9a01c470f65e713d5ec792547c8269ab95a2fb4504b|44cb9c5ae0338a701f4c7940faf5e2dc7311797aa4c55c5b18f58149fe0ef05d|44cb9c5ae0338a701f4c7940faf5e2dc7311797aa4c55c5b18f58149fe0ef05d', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-007", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Glass objects in unusual numbers came from an Anglo-Saxon cemetery here. The chalk hill also holds an Iron Age hillfort, and a WWII radar station and the 1987 Great Storm damaged the site."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "glass objects came from the cemetery [S2]; the number of glass objects was unusual [S2]; there is an Anglo-Saxon cemetery at the site [S1, S2]; the site is a chalk hill [S1]; the hill also holds an Iron Age hillfort [S1]; a WWII radar station damaged the site [S3]; the 1987 Great Storm damaged the site [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-011 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Glass objects in unusual numbers came from an Anglo-Saxon cemetery here. [SUPPORTED: https://wtm.uk/museum/collections/archaeology/]; There is an Anglo-Saxon cemetery here. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA128542]; It is a chalk hill. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA128542]; The hill also holds an Iron Age hillfort. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA128542]; A radar station stood on the site in WWII. [SUPPORTED: http://www.sussexarch.org.uk/saaf/highdown.html]; The WWII radar station damaged the site. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA128542]; The 1987 Great Storm damaged the site. [SUPPORTED: https://heritagerecords.nationaltrust.org.uk/HBSMR/MonRecord.aspx?uid=MNA128542]"}]'::jsonb),
    ('437d6dda-8c48-4142-91fe-575c140b961a'::uuid, 'card_description', 'On Ramsley Moor in the Peak District, in a field of cairns, Barbrook One sets one standing stone and 11 smaller ones in a circle about 13 metres across, ringed by a rubble bank.', 'A single standing stone, 1 metre high, rises among 11 much smaller stones. The stone circle is ringed by a bank of rubble and stands in a field of cairns on the moor.', 'teaser-card-s041:437d6dda-8c48-4142-91fe-575c140b961a:card_description', 'teaser-card-s041 (teaser-card): teaser card, 166 characters, checked PASS, web-verified VERIFIED', '299c1a74cfea802ac55ac910817d21b7a80bf825560078eb5ef869d40a303e4c|31275141a391fd94eac59ae9c6270a5f7c66a3ddd16e7090792149ef6a22b12c|31275141a391fd94eac59ae9c6270a5f7c66a3ddd16e7090792149ef6a22b12c', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-write-007", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A single standing stone, 1 metre high, rises among 11 much smaller stones. The stone circle is ringed by a bank of rubble and stands in a field of cairns on the moor."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-007 (check), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "there is one large standing stone [S3]; it is 1 metre high [S3]; it stands among 11 smaller stones (5 to 25 cm high, so much smaller) [S3]; the site is a stone circle [S1, S2]; the circle is ringed by a rubble bank [S4]; it stands in a cairn field [S5]; it is on a moor [S1, S5]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A single standing stone rises among much smaller stones (the one tall stone of this stone circle) [SUPPORTED: https://derbyshireheritage.co.uk/historical/stone-circles/barbrook-i-stone-circle/]; The standing stone is 1 metre high [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR3996]; There are 11 much smaller stones besides it [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR3996]; It is a stone circle [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR3996]; The stone circle is ringed by a bank of rubble [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR3996]; It stands in a field of cairns [SUPPORTED: https://her.derbyshire.gov.uk/Monument/MDR4001]; It stands on the moor [SUPPORTED: http://www.stone-circles.org.uk/stone/barbrook1.htm]"}]'::jsonb),
    ('43ee9ef2-ada7-4796-98eb-4d2ba9728d74'::uuid, 'card_description', 'Iron Age broch on the Sutherland coast, active 800 BC to the 1st century AD. Kintradwell is a northeastern tower-fort of the Highlands, a round defensive structure of the Atlantic Iron Age tradition.', 'A rock-cut well with steps, over 2 m deep, lay inside this Iron Age tower. Its entrance passage was found to be 2.1 m high, unusually tall for its kind, and a large settlement surrounds it.', 'teaser-card-s041:43ee9ef2-ada7-4796-98eb-4d2ba9728d74:card_description', 'teaser-card-s041 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'f683a541e3861cd19f961e5d0acb264211d8d91f8f047455f2fe56ab73206f20|069c43c515c62e14d10c48a595876335bc580e8e525089940636e78401b1072a|069c43c515c62e14d10c48a595876335bc580e8e525089940636e78401b1072a', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A rock-cut well with steps, over 2 m deep, lay inside this Iron Age tower. Its entrance passage was found to be 2.1 m high, unusually tall for its kind, and a large settlement surrounds it."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "a rock-cut well was found inside the tower [S2]; the well has steps [S2]; the well is over 2 m deep [S2]; it is an Iron Age tower [S1, S2]; excavation found the entrance passage to be 2.1 m high [S2]; that height is unusually tall for its kind [S2]; a large (extensive) settlement surrounds it [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify-012 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "A rock-cut well lay inside this Iron Age tower [SUPPORTED: https://her.highland.gov.uk/Monument/MHG9777]; The well had steps [SUPPORTED: https://her.highland.gov.uk/Monument/MHG9777]; The well was over 2 m deep [SUPPORTED: https://her.highland.gov.uk/Monument/MHG9777]; The site is an Iron Age tower [SUPPORTED: https://her.highland.gov.uk/Monument/MHG9777]; Its entrance passage was found to be 2.1 m high [SUPPORTED: https://her.highland.gov.uk/Monument/MHG9777]; That entrance height is unusually tall for its kind [SUPPORTED: https://her.highland.gov.uk/Monument/MHG9777]; A large settlement surrounds it [SUPPORTED: https://her.highland.gov.uk/Monument/MHG9777]"}]'::jsonb),
    ('44cf60cc-9ced-49af-acc5-9922cc3d6f38'::uuid, 'card_description', 'Excavations in 2003 beneath a school''s sports fields at Bradford on Avon revealed Roman-era floor mosaics and a stone structure identified as an early Christian baptistery.', 'Floor mosaics and walls of a Roman-era villa lie beneath a set of sports fields. Digs also revealed a stone structure believed to have been part of an early Christian baptistery.', 'teaser-card-s041:44cf60cc-9ced-49af-acc5-9922cc3d6f38:card_description', 'teaser-card-s041 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '14a8017fd282148d1fdc27871d3579e0cb082cdc08d111326b22323a9687e313|ee94d071d97ca5ddd56a461244576073759aac32726ce3b3b39fac7a42a65f3c|ee94d071d97ca5ddd56a461244576073759aac32726ce3b3b39fac7a42a65f3c', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Floor mosaics and walls of a Roman-era villa lie beneath a set of sports fields. Digs also revealed a stone structure believed to have been part of an early Christian baptistery."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "floor mosaics of a Roman-era villa were found [S3]; walls of the villa were found [S3]; the villa lies beneath sports fields [S2]; excavations revealed a stone structure [S4]; the structure is believed to have been part of an early Christian baptistery [S4]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-004 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Floor mosaics of a Roman-era villa lie beneath a set of sports fields [SUPPORTED: https://en.wikipedia.org/wiki/Bradford-on-Avon]; Walls of the villa lie beneath the sports fields [SUPPORTED: http://www.bbc.co.uk/wiltshire/features/boa_mosaic.shtml]; The villa is Roman-era [SUPPORTED: http://www.bbc.co.uk/wiltshire/features/boa_mosaic.shtml]; The villa had floor mosaics [SUPPORTED: https://www.bradfordonavonmuseum.co.uk/budbury-villa]; Digs revealed a structure believed to have been part of an early Christian baptistery [SUPPORTED: https://www.bradfordonavonmuseum.co.uk/budbury-villa]; The structure the digs revealed is made of stone [UNVERIFIABLE, no proving quote: None]"}]'::jsonb),
    ('456ddcd7-75de-4626-b009-3172c196249d'::uuid, 'card_description', 'On Harland Edge above Chatsworth House lies Hob Hurst''s House, a Bronze Age barrow. In 1853 the Barrow Knight dug in and found a stone-lined grave with scorched human bones and lead ore.', 'Scorched human bones lay with some lead ore in a stone-lined grave inside this mound. Thomas Bateman dug into the barrow in 1853, on a moorland edge near the highest part of the moor.', 'teaser-card-s041:456ddcd7-75de-4626-b009-3172c196249d:card_description', 'teaser-card-s041 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '24f2debbd0ece661aac3cf9ff31c4472ddadad7fa9a5db2c52b78445b1a00167|ff0dd71ba3e32bc33fc6455d07c103548e82d599ba3f292da7d1521320192b56|ff0dd71ba3e32bc33fc6455d07c103548e82d599ba3f292da7d1521320192b56', '[{"source": "lane WB run wb-shorts-wave-a1-2026-10-24: writer card_writer:teaser-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Scorched human bones lay with some lead ore in a stone-lined grave inside this mound. Thomas Bateman dug into the barrow in 1853, on a moorland edge near the highest part of the moor."}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: checker card_fact_checker:teaser-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "scorched human bones were found in a stone-lined grave [S5]; some lead ore lay with the bones [S5]; the grave is inside a mound (barrow) [S1, S5]; Thomas Bateman excavated the barrow [S4]; the excavation was in 1853 [S4]; the barrow is on a moorland edge [S1, S3]; it lies near the highest part of the moor [S3]"}, {"source": "lane WB run wb-shorts-wave-a1-2026-10-24: verifier card_web_verifier:teaser-verify2-005 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-shorts-wave-a1-2026-10-24/OUTCOMES.jsonl", "quote": "Scorched human bones lay with some lead ore in a stone-lined grave inside this mound. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/hob-hursts-house/history/]; The bones in the grave were scorched (burnt) human bones. [SUPPORTED: https://derbyshireheritage.co.uk/historical/burial-sites/hob-hursts-house/]; Some lead ore lay with the bones. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/hob-hursts-house/history/]; The grave inside the mound was stone-lined. [SUPPORTED: https://www.britainexpress.com/counties/derbyshire/ancient/Hob-Hursts-House.htm]; The site is a barrow (a burial mound). [SUPPORTED: https://www.britainexpress.com/counties/derbyshire/ancient/Hob-Hursts-House.htm]; Thomas Bateman dug into the barrow. [SUPPORTED: https://derbyshireheritage.co.uk/historical/burial-sites/hob-hursts-house/]; The dig took place in 1853. [SUPPORTED: https://www.britainexpress.com/counties/derbyshire/ancient/Hob-Hursts-House.htm]; The barrow lies on a moorland edge. [SUPPORTED: https://www.english-heritage.org.uk/visit/places/hob-hursts-house/history/]; The barrow lies near the highest part of the moor. [SUPPORTED: https://www.explorepeakdistrict.co.uk/places-to-visit/bakewell/hob-hursts-house/]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 41;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s041', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s041'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s041'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 41 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s041'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'WB/teaser-card'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = 'wb-teaser-card-s041' AND l.table_name = 'card_stats'
   AND l.column_name IN ('card_description')
   AND EXISTS (SELECT 1 FROM card_stats t
                WHERE t.site_id::text = l.row_pk AND CASE l.column_name
                WHEN 'card_description' THEN t.card_description IS NOT DISTINCT FROM l.new_value::character varying
                ELSE false END)
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
